    `),variants$2={closed:{opacity:0,y:"100%"},open:{opacity:1,y:0}},MobileModal=({isOpen:r,handleClose:s,closeLabel:n="Close",header:a,children:l,zIndex:c=10})=>jsxRuntimeExports.jsxs(Container$Y,{as:motion.div,animate:r?"open":"closed",variants:variants$2,initial:"closed",exit:"closed",$zIndex:c,className:"blur-50",children:[a&&jsxRuntimeExports.jsxs(Header$c,{className:"mobile-padding",children:[a,jsxRuntimeExports.jsx(Button$7,{className:"cancel mobile-padding",onClick:s,children:jsxRuntimeExports.jsx(BsXLg,{})})]}),l]}),letter="/static/media/letter.Cb4xYmZC.png",errorIcon="data:image/png;base64,",lightningBlue="/static/media/lightning-blue.B6_MdhNu.png",lightningGreen="/static/media/lightning-green.BLNRGQ_Z.png",lightningRed="/static/media/lightning-red.DkpiUEEr.png",lightningYellow="/static/media/lightning-yellow.BrDH4HQK.png",lightningPurple="/static/media/lightning-purple.Dbg6HhrI.png";function currentColorLightning(r){switch(r){case"blue":return lightningBlue;case"green":return lightningGreen;case"red":return lightningRed;case"yellow":return lightningYellow;default:return lightningPurple}}const Container$X=dt.div(()=>lt`
      display: flex;
